item.command:
/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { dispatch } from './src/dispatch.js';
import { registry } from './src/registry.js';
import { handle as mail } from './src/channels/mail.js';
import { handle as audit } from './src/channels/audit.js';
import { handle as legacy } from './src/channels/legacy.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['registered_files', 'selected_file', 'selected_output', 'unknown_kind_error', 'target_depends_on_runtime_kind', 'legacy_reachable_from_dispatch']);
assert.deepEqual(Object.keys(registry).sort(), ['audit', 'mail']);
assert.equal(registry.mail, mail);
assert.equal(registry.audit, audit);
assert.ok("'!Object.values(registry).includes(legacy));
assert.deepEqual(answer.registered_files, ['"'src/channels/audit.js', 'src/channels/mail.js']);
assert.equal(answer.selected_file, 'src/channels/mail.js');
assert.equal(answer.selected_output, dispatch({kind: 'mail', payload: ' Hi '}));
assert.equal(answer.selected_output, 'mail:hi');
assert.equal(dispatch({kind: 'audit', payload: ' Hi '}), 'audit:\" Hi \"');
assert.throws(() => dispatch({kind: 'legacy', payload: ' Hi '}), {name: 'Error', message: answer.unknown_kind_error});
assert.throws(() => dispatch({kind: 'unknown', payload: ' Hi '}), {name: 'Error', message: 'unknown kind'});
assert.equal(answer.target_depends_on_runtime_kind, true);
assert.equal(answer.legacy_reachable_from_dispatch, false);
console.log('PASS: answer.json matches the registry, dispatch outputs, and unknown-kind errors');
NODE"

